<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0d6efd"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="CRM"><link rel="manifest" href="/manifest.webmanifest"><link rel="icon" href="/pwa-icon.svg" type="image/svg+xml"><title>Вход — CRM</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.login-card{border-radius:18px}.app-mark{width:58px;height:58px;border-radius:16px;background:#0d6efd;color:#fff;display:flex;align-items:center;justify-content:center;font-size:30px;margin-bottom:16px}.form-control{min-height:48px}.btn{min-height:48px}@media(max-width:575.98px){.login-wrap{padding:14px}.login-card .card-body{padding:22px!important}}</style></head><body><div class="container login-wrap"><div class="row justify-content-center align-items-center min-vh-100"><div class="col-md-5 col-lg-4"><div class="card login-card border-0 shadow"><div class="card-body p-4"><div class="app-mark"><i class="bi bi-buildings"></i></div><h3 class="mb-1">CRM организаций</h3><p class="text-secondary mb-4">Войдите в рабочее пространство своей организации</p>@if($errors->any())<div class="alert alert-danger">{{ $errors->first() }}</div>@endif<form method="post" action="{{ route('login.perform') }}">@csrf<div class="mb-3"><label class="form-label">Код организации</label><input name="organization_code" class="form-control" value="{{ old('organization_code') }}" placeholder="Например: zcrb" autocomplete="organization"><div class="form-text">Сотрудникам код выдаёт администратор организации. Суперадмин оставляет поле пустым.</div></div><div class="mb-3"><label class="form-label">Email</label><input name="email" type="email" class="form-control" value="{{ old('email') }}" required autofocus autocomplete="username"></div><div class="mb-3"><label class="form-label">Пароль</label><input name="password" type="password" class="form-control" required autocomplete="current-password"></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="remember" value="1" id="remember"><label class="form-check-label" for="remember">Запомнить меня</label></div><button class="btn btn-primary w-100">Войти</button></form><button id="installPwaLogin" class="btn btn-outline-primary w-100 mt-3 d-none"><i class="bi bi-phone me-2"></i>Установить приложение</button></div></div></div></div></div><script>if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}))}let pwaPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();pwaPrompt=e;document.getElementById('installPwaLogin').classList.remove('d-none')});document.getElementById('installPwaLogin').addEventListener('click',async()=>{if(!pwaPrompt)return;pwaPrompt.prompt();await pwaPrompt.userChoice;pwaPrompt=null;document.getElementById('installPwaLogin').classList.add('d-none')});</script></body></html>